import{_ as t,c as i,o as n,a3 as a}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse(`{"title":"Scrumban","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","frontmatter":{"title":"Scrumban","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban introduction, Scrumban concept, what is Scrumban, Scrumban overview, Scrumban fundamentals, Scrum vs Kanban differences, Scrum vs Kanban, agile methodology, agile framework, Kanban methodology, Scrum methodology, Scrumban process, Scrumban operations guide, Scrumban board, WIP limits, workflow management, how to use a Kanban board, Scrumban benefits, Scrumban characteristics, Scrumban impact, Scrumban use cases, Scrumban adoption benefits, Scrumban Jira setup, Scrumban board template, Scrumban tools, Scrumban collaboration tools, Scrumban workflow, agile project management, work efficiency methodology, iterative work management, bottleneck resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/scrumban"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/scrumban"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/scrumban"}]],"sort":201},"headers":[],"relativePath":"en/agile/scrumban.md","filePath":"en/agile/scrumban.md","lastUpdated":1795293539000}`),r={name:"en/agile/scrumban.md"};function s(o,e,l,c,d,g){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="scrumban" tabindex="-1">Scrumban <a class="header-anchor" href="#scrumban" aria-label="Permalink to “Scrumban”">​</a></h1><blockquote><p><strong>One-Line Summary:</strong> Scrumban is a process that combines Scrum&#39;s structure (roles, ceremonies, and backlog concepts) with Kanban&#39;s flow-centric approach and Work In Progress (WIP) limits. Rather than enforcing the rigidity of sprints, it prioritizes <strong>Flow</strong> and <strong>Pull</strong> while retaining Scrum ceremonies (planning and retrospectives) where needed.</p></blockquote><blockquote><p><strong>Note:</strong> For full-lifecycle project bidding, contracting, delivery of the 125 unified standard artifacts, and the AI Software Development Lifecycle (AI-SDLC), refer to the <strong><a href="/en/methodology/">Empasy Business and Development Methodology Portal</a></strong>.</p></blockquote><h2 id="overview-and-definition" tabindex="-1">Overview and Definition <a class="header-anchor" href="#overview-and-definition" aria-label="Permalink to “Overview and Definition”">​</a></h2><p><strong>Scrumban</strong> is a hybrid process designed to help software development and knowledge work teams manage their workflow flexibly.</p><ul><li><strong>Scrum</strong>: Iterations (sprints), fixed ceremonies (sprint planning, review, retrospective), clearly defined roles</li><li><strong>Kanban</strong>: Visual boards, WIP limits, pull-based work, continuous improvement Scrumban adopts the strengths of both approaches while focusing on <strong>practical flow improvement</strong>.</li></ul><h2 id="when-should-you-use-scrumban" tabindex="-1">When Should You Use Scrumban? <a class="header-anchor" href="#when-should-you-use-scrumban" aria-label="Permalink to “When Should You Use Scrumban?”">​</a></h2><ul><li>Your team currently uses <strong>Scrum</strong>, but frequent changes (urgent requests) make it difficult to bundle work into fixed sprints.</li><li>Your team manages flow with <strong>Kanban</strong>, but needs Scrum-like discipline such as backlog management, prioritization, and regular retrospectives.</li><li>Your team handles maintenance, operations, and support (a mix of operational tasks and new feature development).</li><li>You prioritize <strong>continuous delivery</strong> and flow optimization over upfront predictability.</li></ul><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core Concepts”">​</a></h2><ol><li><strong>Pull System</strong>: Work begins (is pulled into the next column) only when the team has capacity to handle it.</li><li><strong>WIP (Work In Progress) Limits</strong>: Restricting the number of concurrent tasks reduces multitasking and accelerates completion.</li><li><strong>Visualized Board</strong>: Clearly displays the status of work and makes bottlenecks immediately visible.</li><li><strong>Regular Replenishment / Planning</strong>: Populates work from the backlog only when needed (either periodically or when a threshold is reached).</li><li><strong>Measurement and Improvement</strong>: Improves flow using metrics such as cycle time, lead time, and throughput.</li><li><strong>Explicit Policies</strong>: Formalizes column transition criteria, prioritization rules, and the Definition of Ready/Done.</li></ol><h2 id="scrum-vs-kanban-vs-scrumban" tabindex="-1">Scrum vs. Kanban vs. Scrumban <a class="header-anchor" href="#scrum-vs-kanban-vs-scrumban" aria-label="Permalink to “Scrum vs. Kanban vs. Scrumban”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Item</th><th style="text-align:right;">Scrum</th><th style="text-align:left;">Kanban</th><th style="text-align:left;">Scrumban</th></tr></thead><tbody><tr><td style="text-align:left;">Iterations (Sprints)</td><td style="text-align:right;">Yes (fixed length)</td><td style="text-align:left;">No (continuous flow)</td><td style="text-align:left;">Optional / hybrid with short iterations</td></tr><tr><td style="text-align:left;">WIP Limits</td><td style="text-align:right;">Implicit (sprint scope)</td><td style="text-align:left;">Explicit</td><td style="text-align:left;">Explicit (core)</td></tr><tr><td style="text-align:left;">Planning Method</td><td style="text-align:right;">Sprint planning</td><td style="text-align:left;">Replenishment / pull-based</td><td style="text-align:left;">Replenishment + planning as needed</td></tr><tr><td style="text-align:left;">Roles</td><td style="text-align:right;">PO / SM / Dev</td><td style="text-align:left;">Flexible (no prescribed roles)</td><td style="text-align:left;">PO + Flow Manager (or retain SM role)</td></tr><tr><td style="text-align:left;">Goal</td><td style="text-align:right;">Commitment (sprint goal)</td><td style="text-align:left;">Flow optimization</td><td style="text-align:left;">Flow optimization + priority management</td></tr></tbody></table><h2 id="roles-and-responsibilities" tabindex="-1">Roles and Responsibilities <a class="header-anchor" href="#roles-and-responsibilities" aria-label="Permalink to “Roles and Responsibilities”">​</a></h2><ul><li><strong>Product Owner (PO)</strong>: Manages backlog prioritization, coordinates stakeholders, and defines business value</li><li><strong>Flow Manager (or retaining the Scrum Master role)</strong>: Monitors flow, helps remove bottlenecks, and facilitates process improvement</li><li><strong>Team (Developers, Testers, etc.)</strong>: Adheres to defined policies and pulls/completes work within WIP limits</li><li><strong>Stakeholders</strong>: Provide requirements and feedback, and participate in reviews when needed</li></ul><blockquote><p>Adjust roles flexibly to fit your team&#39;s context. The key is ensuring <strong>flow management accountability</strong> is clear.</p></blockquote><h2 id="core-artifacts-and-tools" tabindex="-1">Core Artifacts and Tools <a class="header-anchor" href="#core-artifacts-and-tools" aria-label="Permalink to “Core Artifacts and Tools”">​</a></h2><ul><li><strong>Kanban Board</strong> (physical or digital) — including columns and WIP limits</li><li><strong>Backlog (Prioritized List)</strong> — work candidates ready to be pulled</li><li><strong>Explicit Policies</strong> — column transition rules and definitions (Ready/Done)</li><li><strong>Classes of Service</strong> — priority categories such as Expedite, Fixed Date, and Standard</li><li><strong>Metrics Dashboard</strong>: Cycle time, lead time, throughput, and CFD (Cumulative Flow Diagram)</li></ul><h2 id="board-layout" tabindex="-1">Board Layout <a class="header-anchor" href="#board-layout" aria-label="Permalink to “Board Layout”">​</a></h2><p>Basic Scrumban board (example):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Column</th><th style="text-align:left;">Description</th><th style="text-align:right;">Recommended WIP Limit</th></tr></thead><tbody><tr><td style="text-align:left;">Backlog</td><td style="text-align:left;">All prioritized work items</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:left;">Ready</td><td style="text-align:left;">Work ready to start (eligible to move to Doing)</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:left;">Doing / In Progress</td><td style="text-align:left;">Actively being worked on</td><td style="text-align:right;">3</td></tr><tr><td style="text-align:left;">Code Review</td><td style="text-align:left;">Awaiting review</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:left;">Testing</td><td style="text-align:left;">QA / verification</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:left;">Done</td><td style="text-align:left;">Completed</td><td style="text-align:right;">—</td></tr></tbody></table><p><strong>Simple ASCII Board:</strong></p><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Backlog -&gt; Ready -&gt; [Doing (WIP 3)] -&gt; Code Review (WIP 2) -&gt; Testing (WIP 2) -&gt; Done</span></span></code></pre></div><h2 id="workflow-policy-examples" tabindex="-1">Workflow Policy Examples <a class="header-anchor" href="#workflow-policy-examples" aria-label="Permalink to “Workflow Policy Examples”">​</a></h2><div class="language-text"><button title="Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Policy: Pull Criteria (Moving to Doing)</span></span>
<span class="line"><span>- Card is in the Ready column, and Doing WIP &lt; WIP limit</span></span>
<span class="line"><span>- Work item meets the &#39;Definition of Ready&#39; (requirements, test cases, design, etc.)</span></span>
<span class="line"><span>- Required resources (testers/reviewers) are confirmed available</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Policy: Definition of Done</span></span>
<span class="line"><span>- Code is merged and the build succeeds</span></span>
<span class="line"><span>- Automated and manual tests pass</span></span>
<span class="line"><span>- Deployment (or QA handoff) documentation is complete</span></span></code></pre></div><p><strong>Classes of Service Examples</strong></p><ul><li><strong>Expedite</strong>: Immediate handling (highest work priority; WIP limit exception allowed)</li><li><strong>Fixed Date</strong>: Required by a specific date — requires schedule monitoring</li><li><strong>Standard</strong>: Regular requests</li><li><strong>Intangible</strong>: Long-term value items such as technical debt</li></ul><h2 id="events-and-recommended-cadence" tabindex="-1">Events and Recommended Cadence <a class="header-anchor" href="#events-and-recommended-cadence" aria-label="Permalink to “Events and Recommended Cadence”">​</a></h2><ul><li><strong>Daily Stand-up (Daily, 10–15 minutes)</strong>: Flow-focused (share bottlenecks and blockers rather than status updates on what each person is doing)</li><li><strong>Replenishment / Backlog Refinement (Weekly or as needed)</strong>: Refill the Ready column — reprioritize items</li><li><strong>Planning (As needed)</strong>: Break down large work items (epics) or plan alternatives — keep it brief</li><li><strong>Retrospective (Every 2–4 weeks)</strong>: Process improvement and review of WIP limit adjustments</li><li><strong>Service Delivery Review / Ops Review (Monthly)</strong>: Review SLAs, SLEs, and flow metrics</li></ul><blockquote><p>Unlike Scrum, you do not need to rigidly schedule every meeting. Introduce ceremonies when you observe <strong>friction points disrupting flow</strong>.</p></blockquote><h2 id="estimation-and-planning-methods" tabindex="-1">Estimation and Planning Methods <a class="header-anchor" href="#estimation-and-planning-methods" aria-label="Permalink to “Estimation and Planning Methods”">​</a></h2><ul><li><strong>Keep Story Points</strong>: Suitable for teams transitioning from Scrum; useful for forecasting against throughput.</li><li><strong>No Estimates</strong>: Forecast using simple card counts combined with cycle time and throughput.</li><li><strong>Bucket (Time-Period) Planning</strong>: Replenish work monthly based on achievable throughput.</li><li><strong>Recommendation</strong>: Minimize heavy estimation overhead and forecast using <strong>actual historical data (cycle time, throughput)</strong>.</li></ul><h2 id="core-metrics-definitions-and-usage" tabindex="-1">Core Metrics (Definitions and Usage) <a class="header-anchor" href="#core-metrics-definitions-and-usage" aria-label="Permalink to “Core Metrics (Definitions and Usage)”">​</a></h2><ul><li><strong>Lead Time</strong> = Time from when a card enters the backlog (or is created) to completion</li><li><strong>Cycle Time</strong> = Time from when work starts (Doing) to completion</li><li><strong>Throughput</strong> = Number of cards completed within a specific period</li><li><strong>WIP (Average Work In Progress)</strong></li><li><strong>Cumulative Flow Diagram (CFD)</strong>: Visualizes bottlenecks and flow changes across the cumulative area of each column</li><li><strong>Service Level Expectation (SLE)</strong>: Example: 85% of work items will be completed within 10 days</li></ul><p><strong>Practical Usage Notes</strong></p><ul><li>Little&#39;s Law: <code>WIP = Throughput × Cycle Time</code> (using average values) — useful for forecasting and identifying limits</li><li>Goal: Stabilize cycle time → increase predictability</li></ul><h2 id="transitioning-from-scrum-to-scrumban" tabindex="-1">Transitioning from Scrum to Scrumban <a class="header-anchor" href="#transitioning-from-scrum-to-scrumban" aria-label="Permalink to “Transitioning from Scrum to Scrumban”">​</a></h2><ol><li><strong>Map the Current Process</strong>: Visualize how work currently flows</li><li><strong>Configure the Board</strong>: Start with minimal columns (Ready → Doing → QA → Done)</li><li><strong>Set WIP Limits</strong>: Start conservatively (e.g., Doing = number of team members ÷ 2)</li><li><strong>Define Replenishment Rules</strong>: Decide when to pull items from Backlog into Ready (weekly or threshold-based)</li><li><strong>Collect Data</strong>: Gather cycle time and throughput data (2–4 weeks)</li><li><strong>Iterate and Adjust</strong>: Refine WIP limits, columns, and policies during retrospectives</li></ol><h2 id="kanban-scrumban-adoption-checklist" tabindex="-1">Kanban/Scrumban Adoption Checklist <a class="header-anchor" href="#kanban-scrumban-adoption-checklist" aria-label="Permalink to “Kanban/Scrumban Adoption Checklist”">​</a></h2><ul><li>[ ] Does the board reflect the team&#39;s actual workflow?</li><li>[ ] Are WIP limits set and understood by everyone?</li><li>[ ] Are the Definition of Ready and Definition of Done documented?</li><li>[ ] Is a replenishment cadence (or trigger rule) established?</li><li>[ ] Do daily stand-ups focus on resolving bottlenecks?</li><li>[ ] Are cycle time, throughput, and CFD collected and analyzed?</li><li>[ ] Are classes of service and explicit policies defined?</li><li>[ ] Are process changes reflected in regular retrospectives?</li></ul><h2 id="practical-tips-and-best-practices" tabindex="-1">Practical Tips and Best Practices <a class="header-anchor" href="#practical-tips-and-best-practices" aria-label="Permalink to “Practical Tips and Best Practices”">​</a></h2><ul><li><strong>Start Small</strong>: Keep the initial board and WIP limits small to gather fast feedback.</li><li><strong>Stop Starting — Start Finishing</strong>: Build a culture of finishing active work before starting new items.</li><li><strong>Team Discipline on WIP Violations</strong>: Discuss immediately when a limit is breached (identify why it happened and the root bottleneck).</li><li><strong>Visual Signals</strong>: Mark blockers and expedite cards with distinct colors or stickers.</li><li><strong>Document Policies</strong>: Explicitly write down the criteria for &quot;when a card moves to the next column.&quot;</li><li><strong>Automation</strong>: Shorten cycle time with CI/CD and automated testing.</li><li><strong>Data-Driven Decisions</strong>: Plan using actual cycle time and throughput rather than guesswork estimates.</li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to “Common Mistakes”">​</a></h2><ul><li>Setting WIP limits without enforcing them</li><li>Keeping Scrum ceremonies intact while ignoring WIP and pull principles</li><li>Creating classes of service and applying them inconsistently (causing priority confusion)</li><li>Making decisions by &quot;gut feel&quot; without collecting metrics</li><li>Overcomplicating the board with too many columns or excessive granularity</li></ul><h2 id="template-replenishment-meeting-brief-agenda" tabindex="-1">Template: Replenishment Meeting (Brief Agenda) <a class="header-anchor" href="#template-replenishment-meeting-brief-agenda" aria-label="Permalink to “Template: Replenishment Meeting (Brief Agenda)”">​</a></h2><ol><li>Brief review of work completed last week — 5 min</li><li>Check Ready column status (re-order priorities) — 10–20 min</li><li>Check current available capacity against WIP limits — 5 min</li><li>Decide on new work to pull (fill in priority order) — 10–20 min</li><li>Share blockers and risks — 5 min</li></ol><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Q. Do sprints disappear completely?</strong> A. If the team prefers, you can retain short iterations (e.g., 2 weeks) while applying Scrumban principles. The focus is improving flow.</p><p><strong>Q. Should we continue using story points?</strong> A. Not necessarily. Many teams forecast using throughput and cycle time instead. Decide based on team culture and reporting needs.</p><p><strong>Q. How should we determine WIP limits?</strong> A. Start conservatively (based on team size or estimated from past throughput), then adjust gradually while respecting the limits.</p><h2 id="implementation-example" tabindex="-1">Implementation Example <a class="header-anchor" href="#implementation-example" aria-label="Permalink to “Implementation Example”">​</a></h2><ul><li>Team of 5 → Doing WIP = 3 (limits concurrent work)</li><li>Replenishment: Weekly (Mondays)</li><li>Retrospective: Every 2 weeks (hybrid online/in-person)</li><li>Metrics: Track weekly throughput + 4-week rolling cycle time</li></ul><h2 id="conclusion-—-getting-started-guide" tabindex="-1">Conclusion — Getting Started Guide <a class="header-anchor" href="#conclusion-—-getting-started-guide" aria-label="Permalink to “Conclusion — Getting Started Guide”">​</a></h2><ol><li><strong>Build the board</strong>,</li><li><strong>Set WIP limits</strong>,</li><li><strong>Document pull rules and Definitions</strong>, and then</li><li><strong>Collect data (cycle time and throughput) for 2–4 weeks</strong> and <strong>adjust in retrospectives</strong>.</li></ol>`,53)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
